SELECT DISTINCT
    CALENDARYEARMONTH AS CALENDAR_YEAR_MONTH,
    FIRSTDAYOFMONTH AS FIRST_DAY_OF_MONTH,
    LASTDAYOFMONTH AS LAST_DAY_OF_MONTH,
    CALENDARQUARTER AS CALENDAR_QUARTER,
    CALENDARYEARQTR AS CALENDAR_YEAR_QUARTER,
    CALENDARYEARQTRDASH AS CALENDAR_YEAR_QUARTER_DASH,
    CALENDARYEAR AS CALENDAR_YEAR,
    MONTHOFYEAR AS MONTH_OF_YEAR
FROM {{ source('eli_dv_bv', 'ref_rt_ref_calendar') }}